<?php require __DIR__.'/../config/functions.php'; require_admin(); $db=get_db(); if($_SERVER['REQUEST_METHOD']==='POST'){ foreach($_POST['s'] as $k=>$v){$db->prepare('REPLACE INTO site_settings(name,value) VALUES(?,?)')->execute(array($k,$v));} } $rows=$db->query('SELECT * FROM site_settings')->fetchAll(); $s=array(); foreach($rows as $r)$s[$r['name']]=$r['value']; page_header('站点配置'); ?><form class="card" method="post"><h2>站点配置</h2><label>网站名称<input name="s[site_name]" value="<?php echo esc(isset($s['site_name'])?$s['site_name']:'');?>"></label><label>前台样式主题<input name="s[theme]" value="<?php echo esc(isset($s['theme'])?$s['theme']:'default');?>"></label><label>对话/图片/视频定价<input name="s[pricing]" value="<?php echo esc(isset($s['pricing'])?$s['pricing']:'1,2,5');?>"></label><label>合规提示<textarea name="s[compliance_text]"><?php echo esc(isset($s['compliance_text'])?$s['compliance_text']:'');?></textarea></label><button>保存</button><a class="btn" href="backup.php">数据备份</a></form><?php page_footer(); ?>
